import {sharedAmmoRows} from './squad-ammo.js';
import {pairedInHand} from './one-handed.js';
import {isDeceased} from './mercenary-status.js';
import {inventoryAction,transferPreview,nearbyRecipients,nearbyLoot,itemName} from './battle-inventory.js';
import {carryCapacity,loadMultiplier} from './inventory-tools.js';
import {pileOpen,searchPreview} from './core/engine.js';
import {WEAPONS,canControl,combatCosts,equipCost} from './core/engine.js';
import {gridEntries,gridLayout,loadWeight} from './core/inventory.js';
import {characterArt} from './character-art.js';
import {inventoryArt} from './loot-art.js';
import {weaponIcon,createWeaponSprite} from './weapon-icons.js';
export {STAT_DEFINITIONS as CHARACTER_STATS} from './character-stats.js';
import {STAT_DEFINITIONS as CHARACTER_STATS} from './character-stats.js';
const bounded=v=>Number.isFinite(v)?Math.max(1,Math.min(100,Math.round(v))):null;
export function equipmentBlockReason(state,u,{busy=false}={}){
 if(!canControl(state,u))return state.phase==='enemy'?'Wait for your turn to change equipment.':'This character cannot change equipment right now.';
 if(busy)return 'An action is in progress. Close Inventory and resume to finish it before changing equipment.';
 if(state.queue.length)return 'Movement is queued. Stop squad movement to change equipment here.';
 return '';
}
export function characterSheet(u,{equipmentState='carried',state=null}={}){
 const legacy={medical:u.medical,perception:u.perception,sneak:u.stealth},stats=CHARACTER_STATS.map(([key,label])=>({key,label,value:bounded(u.stats?.[key]??legacy[key])}));
 const equipment=(u.slots||[]).filter(Boolean).map(kind=>({type:kind==='wireCutters'?'utility':'weapon',kind,held:kind===u.weapon||pairedInHand(u,kind),stowed:kind===u.weapon&&equipmentState==='stowed',jammed:u.pack?.find(i=>i.type==='weapon'&&i.kind===kind)?.jammed,condition:u.pack?.find(i=>i.type==='weapon'&&i.kind===kind)?.condition??100,drawing:kind===u.weapon&&equipmentState==='drawing',rounds:u.ammo?.[kind]}));
 if(u.weapon==='hands')equipment.unshift({type:'weapon',kind:'hands',held:true});
 const layout=gridLayout(u),backpack=gridEntries(u).map(e=>({...e,
  // Firing updates u.ammo; the carried item's rounds may still be cached.
  item:e.item.type==='weapon'?{...e.item,rounds:u.ammo?.[e.item.kind]??e.item.rounds}:e.item,
  cell:layout.entries.find(p=>p.key===e.key)?.cell}));
 return {name:u.name,species:u.species,portrait:characterArt(u.species,'hands').src,deceased:isDeceased(u),stats,equipment,sharedAmmo:sharedAmmoRows(state||{units:[u]}),backpack,weight:loadWeight(u),hp:u.hp,maxHp:u.maxHp,ap:u.ap,maxAp:u.maxAp,stamina:u.stamina,maxStamina:u.maxStamina,damageResistance:u.damageResistance,carryCapacity:carryCapacity(u),loadMultiplier:loadMultiplier(u,loadWeight(u))};
}
const el=(tag,cls,text)=>{const e=document.createElement(tag);if(cls)e.className=cls;if(text!==undefined)e.textContent=text;return e;};
function itemCard(item){const name=itemName(item),label=item.type==='ammo'?name+' ammunition':name,card=el('div','dossier-item'),painted=item.type==='weapon'&&weaponIcon(item.kind),src=painted||inventoryArt(item);if(painted)card.append(createWeaponSprite(item.kind,{height:50}));else if(src){const image=el('img');image.src=src;image.alt='';card.append(image);}else card.append(el('span','item-symbol',item.kind==='hands'?'✊':'◆'));card.append(el('strong','',label));const details=item.kind==='largeMedicalKit'?`${item.charges}/10 sector treatments · 2 cells`:item.held?(item.stowed?'Stowed':item.drawing?'Drawing':'In hand'):item.type==='ammo'||item.count?'Quantity: '+item.count:item.type==='weapon'&&WEAPONS[item.kind]?.mag?'Loaded: '+(item.rounds??0):'Ready';card.append(el('small','',details));if(item.type==='weapon'&&item.kind!=='hands')card.append(el('small','','Condition: '+(item.condition??100)+'%'));if(item.jammed)card.append(el('small','','Jammed · clear with Reload'));if(item.held&&WEAPONS[item.kind]?.mag)card.append(el('small','','Loaded: '+(item.rounds??0)));return card;}
export function createCharacterScreen({getState,beforeOpen,onOpen,onClose,getEquipmentState=()=> 'carried',onEquip,canEquip=()=>true,onInventoryChange,onStopMovement}){
 const dialog=el('dialog','character-dossier');dialog.id='character-screen';dialog.setAttribute('aria-labelledby','character-name');document.body.append(dialog);let unitId,inventoryNotice='',focusedPile=null;
 function render(){const state=getState(),roster=state.units.filter(u=>u.team==='squad'),u=roster.find(u=>u.id===unitId)||roster[0];if(!u)return;unitId=u.id;const sheet=characterSheet(u,{equipmentState:getEquipmentState(u.id),state});dialog.replaceChildren();
  const top=el('div','dossier-top'),label=el('span','','Personnel / Field record'),close=el('button','','Close ×');close.id='character-close';close.onclick=()=>dialog.close();top.append(label,close);
  const nav=el('nav','dossier-roster');nav.setAttribute('aria-label','Squad character records');for(const merc of roster){const button=el('button','',merc.name);button.setAttribute('aria-pressed',String(merc.id===unitId));button.onclick=()=>{unitId=merc.id;render();dialog.querySelector('[aria-pressed="true"]').focus();};nav.append(button);}
  const body=el('div','dossier-body'),identity=el('section','dossier-identity'),portrait=el('img','dossier-portrait'),portraitBox=el('div','merc-portrait'+(sheet.deceased?' deceased':''));portrait.src=sheet.portrait;portrait.alt=sheet.species+' portrait';portraitBox.append(portrait);if(sheet.deceased)portraitBox.append(el('span','deceased-stamp','Deceased'));const name=el('h2','',sheet.name);name.id='character-name';identity.append(el('p','dossier-kicker','Animal Factory / Mercenary'),name,el('p','',sheet.species.replaceAll('-',' ')+' · '+(sheet.deceased?'Deceased':u.casualty||'Active')),portraitBox);
  const resources=el('dl','dossier-resources');for(const [key,value]of [['Damage resistance',Number.isFinite(sheet.damageResistance)?'-'+sheet.damageResistance+' / hit':'—'],['Health',sheet.hp+' / '+sheet.maxHp],['Action points',sheet.ap+' / '+sheet.maxAp],['Stamina',Number.isFinite(sheet.maxStamina)?Math.floor(sheet.stamina??sheet.maxStamina)+' / '+sheet.maxStamina:'—']])resources.append(el('dt','',key),el('dd','',value));identity.append(resources);
  const stats=el('section','dossier-stats');stats.append(el('h3','','Attributes & skills'),el('p','dossier-kicker','Scale 1–100'));const list=el('dl','stat-list');for(const stat of sheet.stats){const row=el('div','stat-row');row.append(el('dt','',stat.label),el('dd','',stat.value??'—'));const meter=el('div','stat-meter');meter.style.setProperty('--stat',String(stat.value??0)+'%');meter.setAttribute('aria-hidden','true');row.append(meter);list.append(row);}stats.append(list);if(sheet.stats.some(s=>s.value===null)||!Number.isFinite(sheet.maxStamina))stats.append(el('p','dossier-note','— Not assigned yet. Health and AP show current battle values.'));
  const runInventory=a=>{if(!canEquip(u))return;const oldWeapon=u.weapon;if(inventoryAction(state,u,a)){inventoryNotice='Equipment updated.';onInventoryChange?.();if(u.weapon!==oldWeapon){dialog.close();return;}}else inventoryNotice=(['take','give','drop'].includes(a.mode)?transferPreview(state,u,a).reason:null)||'Cannot move this item. Check backpack space, AP and the selected cell.';render();};
  const management=(card,item,key,slot)=>{if(!onInventoryChange||item.kind==='hands')return;const buttons=el('div','item-actions');const button=(label,a,preview)=>{const b=el('button','',label);b.disabled=!canControl(state,u)||!!state.queue.length||!canEquip(u)||preview?.ok===false;b.title=preview?.reason||'';b.onclick=()=>runInventory(a);buttons.append(b);};
   if(slot!==undefined)card.append(el('small','','Ready slot '+(slot+1)));
   if(slot!==undefined)button('To backpack',{mode:'stow',slot});else if(item.type==='weapon'||item.kind==='wireCutters')for(const slot of [0,1])button('Ready '+(slot+1)+(combatCosts(state)?' · 3 AP':''),{mode:'ready',key,slot});
   let quantity=item.type==='weapon'?1:item.count;const input=el('input');if(quantity>1){input.type='number';input.min=1;input.max=quantity;input.value=quantity;input.setAttribute('aria-label','Quantity of '+itemName(item));buttons.append(input);}const count=()=>quantity>1?Number(input.value):quantity;
   const drop=el('button','','Drop'+(combatCosts(state)?' · 2 AP':''));drop.disabled=!canControl(state,u)||!canEquip(u)||!!state.queue.length||!transferPreview(state,u,{mode:'drop',key}).ok;drop.onclick=()=>runInventory({mode:'drop',key,count:count()});buttons.append(drop);
   const recipients=nearbyRecipients(state,u);if(recipients.length){const select=el('select');select.setAttribute('aria-label','Give '+itemName(item)+' to');for(const v of recipients){const opt=el('option','',v.name);opt.value=v.id;select.append(opt);}const give=el('button','','Give'+(combatCosts(state)?' · 2 AP':''));give.disabled=drop.disabled;give.onclick=()=>runInventory({mode:'give',key,count:count(),target:state.units.find(v=>v.id===Number(select.value))});buttons.append(select,give);}
   if(slot===undefined){const cells=el('select');cells.setAttribute('aria-label','Backpack cell for '+itemName(item));for(let cell=0;cell<18;cell++){const opt=el('option','','Cell '+(cell+1));opt.value=cell;cells.append(opt);}cells.value=sheet.backpack.find(e=>e.key===key)?.cell??0;const place=el('button','','Move');place.disabled=!canControl(state,u)||!canEquip(u)||!!state.queue.length;place.onclick=()=>runInventory({mode:'arrange',key,cell:Number(cells.value)});buttons.append(cells,place);}
   card.append(buttons);
  };
  const gear=el('section','dossier-gear'),blockReason=equipmentBlockReason(state,u,{busy:!canEquip(u)});
  const equipmentCard=item=>{const card=itemCard(item);if(onEquip&&item.type==='weapon'){
   const held=item.kind===u.weapon,cost=equipCost(state,u,item.kind),reason=blockReason||(u.ap<cost?'Needs '+cost+' AP; '+u.ap+' available.':''),draw=el('button','weapon-choice'+(held?' is-equipped':' draw-weapon'));
   draw.dataset.weapon=item.kind;draw.disabled=held||!!reason;draw.title=held?'Equipped':reason||'Equip '+itemName(item);draw.setAttribute('aria-label',(held?'Equipped ':'Equip ')+itemName(item)+(held?'':cost?' · '+cost+' AP':' · Free'));
   draw.append(card.querySelector('.weapon-sprite,img,.item-symbol'),card.querySelector('strong'),el('span','weapon-choice-action',held?'Equipped':'Equip · '+(cost?cost+' AP':'Free')));card.prepend(draw);
   if(reason&&!held)card.append(el('small','equipment-block-reason',reason));
   draw.onclick=()=>{if(!draw.disabled&&onEquip(u.id,item.kind))dialog.close();else{inventoryNotice='Could not equip this weapon. Check AP and backpack space.';render();}};
  }return card;};
  gear.append(el('h3','','Held & ready equipment'),el('p','dossier-note','Click a weapon to equip it. Two one-handed ready items are held together; choosing either is free. Other ready swaps cost 2 AP in combat; backpack draws cost 3 AP.'));
  if(blockReason){const notice=el('div','equipment-notice',blockReason);notice.setAttribute('role','status');if(state.queue.length&&onStopMovement&&canControl(state,u)&&canEquip(u)){const stop=el('button','','Stop squad movement');stop.onclick=()=>{if(onStopMovement(u.id))inventoryNotice='Movement stopped. Choose a weapon to equip.';render();};notice.append(stop);}gear.append(notice);}
  const equipped=el('div','dossier-equipment');for(const item of sheet.equipment){const card=equipmentCard(item),key=item.kind==='wireCutters'?'wireCutters':String(u.pack.findIndex(i=>i.type==='weapon'&&i.kind===item.kind));management(card,item,key,u.slots.indexOf(item.kind));equipped.append(card);}if(!sheet.equipment.length)equipped.append(el('p','','No equipment'));gear.append(equipped);
  const ammunition=el('section','dossier-ammunition');ammunition.setAttribute('aria-label','Shared squad ammunition');ammunition.append(el('h3','','Squad ammunition'),el('p','dossier-note','Shared within this sector. No backpack space or carry weight. Loaded magazines stay with each weapon.'));
  const ammoList=el('div','dossier-ammo-grid');for(const item of sheet.sharedAmmo){const row=el('div','dossier-ammo-row'),image=el('img');image.src=inventoryArt({type:'ammo',kind:item.kind});image.alt='';const w=WEAPONS[item.kind],label=(w?.short||item.kind)+(w?.incendiary?' fuel':w?.thrown?' grenades':' ammo');row.append(image,el('span','',label),el('strong','',item.count));ammoList.append(row);}if(!sheet.sharedAmmo.length)ammoList.append(el('p','','No reserve ammunition.'));ammunition.append(ammoList);gear.append(el('h3','','Backpack'),el('p','dossier-kicker',sheet.weight.toFixed(1)+' / '+(Number.isFinite(sheet.carryCapacity)?sheet.carryCapacity.toFixed(1):'—')+' kg comfort load · '+sheet.loadMultiplier.toFixed(2)+'× movement stamina · 18 backpack cells'));
  const pack=el('div','dossier-backpack');for(const entry of sheet.backpack){const card=equipmentCard(entry.item);card.dataset.itemKey=entry.key;card.append(el('small','','Cell '+(entry.cell+1)+(entry.span>1?' · '+entry.span+' cells':'')));card.style.gridColumn='span '+entry.span;management(card,entry.item,entry.key);pack.append(card);}if(!sheet.backpack.length)pack.append(el('p','','Backpack empty'));gear.append(pack);if(inventoryNotice){const notice=el('p','dossier-note',inventoryNotice);notice.setAttribute('role','status');gear.append(notice);}if(onInventoryChange){gear.append(el('h3','','Nearby loot'));const loot=el('div','dossier-loot');for(const pile of nearbyLoot(state,u)){const section=el('section','dossier-item');if(pile===focusedPile){section.dataset.focusedLoot='true';section.tabIndex=-1;}section.append(el('strong','',pile.container?.name||(pile.body===undefined?'Supplies':'Body')));if(!pileOpen(pile)){const search=el('button','',(pile.container?'Search container':'Search body')+(combatCosts(state)?' · 3 AP':''));const p=searchPreview(state,u,pile);search.disabled=!p.ok||!canEquip(u);search.title=p.reason;search.onclick=()=>runInventory({mode:'search',target:pile});section.append(search);}else for(const [index,item]of pile.items.entries()){const card=itemCard(item),a={mode:'take',target:pile,index},p=transferPreview(state,u,a),take=el('button','',(item.type==='ammo'?'Take for squad':'Take')+(combatCosts(state)?' · 2 AP':''));take.disabled=!p.ok||!canEquip(u);take.title=p.reason;take.onclick=()=>runInventory(a);card.append(take);section.append(card);}loot.append(section);}if(!loot.childNodes.length)loot.append(el('p','','Move beside visible supplies or a body to collect equipment.'));gear.append(loot);}body.append(identity,stats,gear);dialog.append(top,nav,ammunition,body);
 }
 dialog.addEventListener('close',()=>onClose?.());return {get open(){return dialog.open;},show(id,{pile=null}={}){beforeOpen?.();unitId=id;focusedPile=pile;inventoryNotice='';render();dialog.showModal();dialog.scrollTop=0;onOpen?.();const focus=dialog.querySelector('[data-focused-loot]')||dialog.querySelector('#character-close');focus.focus({preventScroll:true});if(pile)focus.scrollIntoView({block:'center'});}};
}
